import 'package:flutter/material.dart';import '../data/app_database.dart';import '../data/dataset.dart';import 'scan_page.dart';import 'dataset_page.dart';import 'product_form_page.dart';
class AppShell extends StatefulWidget{const AppShell({super.key});@override State<AppShell> createState()=>_AppShellState();}
class _AppShellState extends State<AppShell>{int index=0;String datasetId='default-supermarket',datasetName='منتجات السوبرماركت';List<Dataset> datasets=[];String pendingBarcode='';
 @override void initState(){super.initState();_load();}
 Future<void> _load() async{final l=await AppDatabase.instance.datasets();if(!mounted)return;setState((){datasets=l;if(!l.any((d)=>d.id==datasetId)&&l.isNotEmpty){datasetId=l.first.id;datasetName=l.first.name;}});}
 Future<void> _create() async{final c=TextEditingController();final n=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:const Text('مجموعة بيانات جديدة'),content:TextField(controller:c,decoration:const InputDecoration(labelText:'اسم المجموعة')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(ctx,c.text.trim()),child:const Text('إنشاء'))]));if(n==null||n.isEmpty)return;final d=Dataset(id:'ds-${DateTime.now().microsecondsSinceEpoch}',name:n,createdAt:DateTime.now().toIso8601String());await AppDatabase.instance.saveDataset(d);await _load();setState(()=>{datasetId=d.id,datasetName=d.name,index=2});}
 @override Widget build(BuildContext context){final pages=[ScanPage(datasetId:datasetId,onBarcode:(b){setState(()=>{pendingBarcode=b,index=1});},onManual:()=>setState(()=>index=1)),ProductFormPage(key:ValueKey('$datasetId-$pendingBarcode'),datasetId:datasetId,datasetName:datasetName,initialBarcode:pendingBarcode,onSaved:(){setState(()=>{index=2,pendingBarcode=''});}) ,DatasetPage(key:ValueKey(datasetId),datasetId:datasetId,datasetName:datasetName,onAdd:()=>setState(()=>index=1))];return Scaffold(appBar:AppBar(title:Text(['مسح منتج','إضافة منتج','مجموعة البيانات'][index],style:const TextStyle(fontWeight:FontWeight.w700)),actions:[if(index==2)IconButton(onPressed:_create,icon:const Icon(Icons.create_new_folder_outlined),tooltip:'مجموعة بيانات جديدة')]),body:IndexedStack(index:index,children:pages),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:const[NavigationDestination(icon:Icon(Icons.qr_code_scanner),label:'مسح'),NavigationDestination(icon:Icon(Icons.add_box_outlined),label:'المنتج'),NavigationDestination(icon:Icon(Icons.inventory_2_outlined),label:'قاعدة البيانات') ]));}
}
